// DeleteTable is the resolver for the deleteTable field.
func (r *mutationResolver) DeleteTable(ctx context.Context) (bool, error) {
	// List of tables to drop
	tables := []string{
		"cart_items", // Drop child tables first
		"orders",     // Then parent tables
		"products",
		"chat_messages",
		"job_requests",
		"admins",
	}

	// Drop each table with CASCADE
	for _, tableName := range tables {
		query := fmt.Sprintf("DROP TABLE IF EXISTS %s CASCADE;", tableName)

		// Log the query being executed
		fmt.Printf("Executing query: %s\n", query)

		if err := r.DB.Exec(query).Error; err != nil {
			return false, fmt.Errorf("failed to delete table %s: %w", tableName, err)
		}
	}

	return true, nil
}

