func (r *mutationResolver) UserBookings(ctx context.Context, bookTypeID string, userID *string, tableSize *int32, notes *string, bookType *string) (*model.UserBookings, error) {
	if userID == nil {
		return nil, fmt.Errorf("user ID must be provided")
	}

	if bookType == nil {
		return nil, fmt.Errorf("bookType must be provided")
	}

	var serviceID string
	switch *bookType {
	case "EVENT":
		var event model.Event
		if err := r.DB.Where("id = ?", bookTypeID).First(&event).Error; err != nil {
			if errors.Is(err, gorm.ErrRecordNotFound) {
				return nil, fmt.Errorf("event not found with ID: %s", bookTypeID)
			}
			return nil, fmt.Errorf("failed to fetch event: %w", err)
		}
		serviceID = event.ServiceID // Get ServiceID from event
	case "RENTAL":
		var inventory model.InventoryItem
		if err := r.DB.Where("id = ?", bookTypeID).First(&inventory).Error; err != nil {
			if errors.Is(err, gorm.ErrRecordNotFound) {
				return nil, fmt.Errorf("inventory item not found with ID: %s", bookTypeID)
			}
			return nil, fmt.Errorf("failed to fetch inventory item: %w", err)
		}
		serviceID = *inventory.ServiceID // Get ServiceID from inventory
	default:
		return nil, fmt.Errorf("invalid bookType: %s", *bookType)
	}

	// Check if user already booked this
	var existing model.UserBookings
	if err := r.DB.Where("book_type_id = ? AND user_id = ?", bookTypeID, *userID).First(&existing).Error; err == nil {
		return nil, fmt.Errorf("user has already booked this %s", strings.ToLower(*bookType))
	} else if !errors.Is(err, gorm.ErrRecordNotFound) {
		return nil, fmt.Errorf("failed to check existing bookings: %w", err)
	}

	newBooking := &model.UserBookings{
		BookTypeID: bookTypeID,
		BookType:   *bookType,
		ServiceID:  serviceID,
		UserID:     *userID,
		IsBooked:   true,
	}

	if tableSize != nil {
		newBooking.TableSize = tableSize
	}
	if notes != nil {
		newBooking.Notes = notes
	}

	if err := r.DB.Create(newBooking).Error; err != nil {
		return nil, fmt.Errorf("failed to create user booking: %w", err)
	}

	return newBooking, nil
}

